//  Module Declaration
module rspsignals
(
// {{ALTERA_ARGS_BEGIN}} DO NOT REMOVE THIS LINE!
Q, Y
// {{ALTERA_ARGS_END}} DO NOT REMOVE THIS LINE!
);
// Port Declaration

// {{ALTERA_IO_BEGIN}} DO NOT REMOVE THIS LINE!
input [3:0] Q;
output [2:0] Y;
// {{ALTERA_IO_END}} DO NOT REMOVE THIS LINE!

// Блок rspsignals: распределитель сигналов.
// Последовательность y: 2,1,3,2,3,1,3,2,...
// y = k означает единицу на выходе Y[k-1]:
// Y[0] -> LEDR1, Y[1] -> LEDR2, Y[2] -> LEDR3.
reg [2:0] Y;

always @(Q)
    case (Q)
        4'b0000 : Y = 3'b010; // y = 2
        4'b0001 : Y = 3'b001; // y = 1
        4'b0011 : Y = 3'b100; // y = 3
        4'b0111 : Y = 3'b010; // y = 2
        4'b1111 : Y = 3'b100; // y = 3
        4'b1110 : Y = 3'b001; // y = 1
        4'b1100 : Y = 3'b100; // y = 3
        4'b1000 : Y = 3'b010; // y = 2
        default : Y = 3'b000; // запрещённое состояние
    endcase

endmodule
